 bool materialOk=true; var material=new JsonArray();foreach(var item in new[]{(new Vector2(722,459),"left-leg-"),(new Vector2(739.5f,451.5f),"right-leg-"),(new Vector2(744,452),"bed-left-")}){var p=item.Item1;var owners=entries.Where(v=>v.Visual!.GlobalBounds.HasPoint(p)&&v.Visual.Covers(p)).Select(v=>Owner(v.Node)).ToArray();material.Add(new JsonObject{{"point",new JsonArray(p.X,p.Y)},{"actualSupportOwners",new JsonArray(owners.Select(v=>(JsonNode)JsonValue.Create(v)!).ToArray())}});if(!owners.Any(v=>v.StartsWith(item.Item2)))materialOk=false;}
 var report=new JsonObject{{"scope","Formal runtime material and pair-order audit of rear-west seat/bed/root. Draw/pick compiler source, no second wrapper; static empty display clone, no commands/saves."},{"scene",path},{"pairs",rows},{"stoneMaterialOwners",material},{"stateUnchanged",digest==EcmaJson.Stringify(s)},{"issues",b.RenderingIssueCount}};var output=OS.GetEnvironment("C07_REAR_WEST_OUTPUT");if(output.Length==0)output="res://central-rear-west-ownership-result.json";File.WriteAllText(ProjectSettings.GlobalizePath(output),report.ToJsonString());
 if(!materialOk)throw new Exception("Rear west visible wood ends and independent new stone wall require their actual material owners"); if(rows.Take(2).Sum(v=>v!["aboveRootOverlap"]!.GetValue<int>())==0||rows.Take(2).Any(v=>v!["coveredAboveRoot"]!.GetValue<int>()!=0))throw new Exception("Rear west carrier above-root foliage must retain its physical ground projection");if(digest!=EcmaJson.Stringify(s)||b.RenderingIssueCount!=0)throw new Exception("Static assembly state/render changed");GD.Print("CENTRAL_REAR_WEST_OWNERSHIP_COMPLETE");GetTree().Quit();
 }catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
